  // ================================================================
  nkrumah: {
    oneLine: "Organisation and a voice of his own: Nkrumah built colonial Africa's first mass party out of an elite movement's youth wing, owned his own newspaper and ran the party from a prison cell — then used the same machinery to detain opponents and build a cult around himself.",
    ownWords: [
      { text: "Seek ye first the political kingdom", src: "His slogan, adapted from Matthew 6:33, used in speeches and in his autobiography, Ghana (1957)" },
      { text: "He chose the word 'convention' for the new party, he said, to carry the masses with him.", src: "Paraphrase of his explanation of the party's name, 1949", para: true }
    ],
    rhythm: [],
    rhythmSrc: "His daily routine is not well documented in the sources used here. The record is of organising methods, not of hours.",
    practices: [
      { id: "students", cat: "network", name: "Organising the students abroad", stage: "1935–47 — student in the United States and London",
        what: "In Pennsylvania he organised expatriate African students into what became the African Students Association of America and Canada, and served as its president. Back in London from May 1945 he became secretary of the West African National Secretariat and, with George Padmore, was a principal organiser and co-treasurer of the Fifth Pan-African Congress in Manchester, 15–19 October 1945. He also set up a Coloured Workers Association to help stranded West African seamen.",
        volume: null,
        mechanism: "He came home in 1947 with an organiser's record and a pan-African network, which is why the United Gold Coast Convention hired him as its general secretary.",
        cost: "Formal study left unfinished: he withdrew from a doctorate at the LSE after one term.",
        tryit: "Run the association in the place you are passing through. The people you organise at twenty-five are the network you call on at thirty-five.",
        attrib: ["self", "biographer"], grade: "documented", source: "Nkrumah, Ghana (1957); Birmingham, Kwame Nkrumah" },
      { id: "eveningnews", cat: "persuasion", name: "Owning a newspaper", stage: "1948–50",
        what: "While still general secretary of the UGCC he founded the Accra Evening News, owned by himself and associates rather than by the party, and used it to speak directly to the young, urban, newly literate readers whom the movement's elders ignored. It was banned when he was arrested in January 1950.",
        volume: null,
        mechanism: "A channel he controlled meant his message did not pass through the UGCC leaders he was about to break with.",
        cost: "It made him, in the colonial government's eyes, the agitator to be locked up.",
        tryit: "Own a channel to your audience — a newsletter, a list, a regular note — so that what you say reaches people in your words, not someone else's.",
        attrib: ["biographer"], grade: "documented", source: "Birmingham, Kwame Nkrumah; Nkrumah, Ghana" },
      { id: "cpp", cat: "machine", name: "Breaking away with the youth", stage: "12 June 1949",
        what: "When the UGCC leaders moved against him he took its youth wing, the Committee on Youth Organisation, with its motto 'Self-Government Now', and announced the Convention People's Party on 12 June 1949. It had a red cockerel emblem, red, white and green colours worn on clothes and painted on flags, vehicles and houses, the slogan 'Forward Ever, Backward Never', and vans in party colours that toured the country playing music and gathering support.",
        volume: null,
        mechanism: "Symbols, colours and touring vans turned a political programme into something people could join, wear and see. His rivals had a manifesto; he had a membership.",
        cost: "A party built round one man's name made it easier, later, to make party and state the same thing.",
        tryit: "Give the people you want on your side something to join and a visible way to belong.",
        attrib: ["biographer"], grade: "documented", source: "Birmingham, Kwame Nkrumah; Jackson & Rosberg, Personal Rule in Black Africa" },
      { id: "prison", cat: "machine", name: "Running the party from a cell", stage: "January 1950 – February 1951",
        what: "Arrested on 22 January 1950 after the 'Positive Action' strikes, he was sentenced to three years and held with common criminals in James Fort, Accra. He kept directing the party through notes written on toilet paper and smuggled out, while Komla Gbedemah ran it day to day. In the February 1951 election — the first under universal franchise in colonial Africa — the CPP won 34 of the 38 seats contested by parties; Nkrumah won Accra from prison, was released on 12 February and was asked to form a government the next day.",
        volume: "34 of 38 party-contested seats",
        mechanism: "A trusted deputy outside and a steady line of instructions from inside kept the organisation working — and imprisonment made him a martyr.",
        cost: "Fourteen months in prison, and the standing risk that the deputy who runs things in your absence becomes a rival.",
        tryit: "Before you are unavailable — illness, travel, leave — name who runs things and agree how you will communicate. Short, regular notes beat long silences.",
        attrib: ["self", "biographer"], grade: "documented", source: "Nkrumah, Ghana (1957); Birmingham, Kwame Nkrumah" },
      { id: "winneba", cat: "machine", name: "Schooling the cadres", stage: "1961–66",
        what: "Laid the foundation stones of the Kwame Nkrumah Ideological Institute at Winneba in 1961 to train civil servants and party workers in 'Nkrumaism' and pan-Africanism. From 1964 every student entering college in Ghana had to attend a two-week ideological orientation there.",
        volume: "Two weeks for every college entrant, from 1964",
        mechanism: "Common training reproduces a doctrine and the loyalty that goes with it.",
        cost: "Orthodoxy enforced on the young produced conformity rather than competence.",
        tryit: "Train your people in how the firm works — but teach methods, not devotion to you. Compulsory loyalty is not one to copy.",
        attrib: ["biographer"], grade: "documented", source: "Birmingham, Kwame Nkrumah; histories of the CPP state" },
      { id: "detention", cat: "intel", name: "Detention without trial", stage: "1958–66",
        what: "In 1958, after an opposition MP was arrested over an alleged plot, he had parliament pass the Preventive Detention Act, allowing detention for up to five years without charge or trial, with only Nkrumah able to order early release. A 1964 referendum made the CPP the only legal party, with 99.91 per cent of the vote — a figure observers called obviously rigged.",
        volume: "Up to 5 years without trial; 99.91% in 1964",
        mechanism: "It removed opponents and silenced dissent.",
        cost: "It also removed the people who would have told him the truth. When the army and police overthrew him in February 1966, he was abroad, on a visit to Beijing.",
        tryit: "Not one to copy. The transferable lesson is the cost: once disagreement is dangerous, you stop hearing it.",
        attrib: ["biographer"], grade: "documented", source: "Jackson & Rosberg, Personal Rule in Black Africa; Birmingham, Kwame Nkrumah" },
      { id: "osagyefo", cat: "persuasion", name: "The cult of the Redeemer", stage: "1957–66",
        what: "Took the title Osagyefo — 'redeemer' in Akan — and put his own image on stamps and money in the manner of a monarch.",
        volume: null,
        mechanism: "It personalised the new state around the man who had led it to independence.",
        cost: "Charisma took the place of institutions — the cost that Jackson and Rosberg make the centre of their study of personal rule.",
        tryit: "Not one to copy. Build the firm's name, not your own image; a business that depends on one person's aura does not outlast him.",
        attrib: ["biographer"], grade: "documented", source: "Jackson & Rosberg, Personal Rule in Black Africa; Birmingham, Kwame Nkrumah" }
    ],
    books: ["nkrumah-birmingham", "personal-rule-black-africa", "nkrumah-ghana-autobiography"]
  },
