  // ================================================================
  obama: {
    oneLine: "Protected time for thinking: Obama kept the day for meetings and the night for reading, writing and deciding, stripped trivial choices out of his life, and read ten letters from citizens every evening as a check on the briefings.",
    ownWords: [
      { text: "He told Michael Lewis he wore only grey or blue suits to pare down decisions, saving his attention for the ones that mattered.", src: "Paraphrase of Michael Lewis, 'Obama's Way', Vanity Fair (October 2012)", para: true }
    ],
    rhythm: [
      { t: "Morning", d: "A workout, then breakfast with his family before going down to the Oval Office." },
      { t: "Day", d: "Meetings and briefings in the West Wing." },
      { t: "≈6:30 pm", d: "Dinner with Michelle and his daughters, kept as a fixed appointment." },
      { t: "Night", d: "Alone in the Treaty Room until about 1 a.m. or later: the briefing book, speech drafts, and the ten letters." }
    ],
    rhythmSrc: "From Michael Lewis's 2012 profile, Michael Shear's 'Obama After Dark' (New York Times, 2016) and his own memoir. Reasonably well described for a modern president; the hours are approximate.",
    practices: [
      { id: "letters", cat: "intel", name: "Ten letters a day", stage: "2009–2017",
        what: "The Office of Presidential Correspondence picked ten letters each day from the thousands that arrived, and they went into his evening briefing folder. He read them at night, answered some by hand and sent others to agencies with notes.",
        volume: "10 a day for eight years",
        mechanism: "An unfiltered sample of the country, chosen to be representative rather than flattering, as a check on what officials told him.",
        cost: "Ten letters is a tiny sample; it informed his sense of things more than it changed policy.",
        tryit: "Read a few raw client messages yourself every week — not a summary of them.",
        attrib: ["self", "witness"], grade: "documented", source: "Jeanne Marie Laskas, To Obama: With Love, Joy, Anger, and Hope (2018); Obama, A Promised Land" },
      { id: "night", cat: "energy", name: "The night shift", stage: "Presidency",
        what: "After dinner with his family he worked alone in the Treaty Room, usually until about 1 a.m. and sometimes later, reading the briefing book and editing speeches.",
        volume: "Four or five hours most nights",
        mechanism: "Uninterrupted hours for the work that needed thought, after the meetings were over.",
        cost: "Short sleep, by his own and his aides' accounts.",
        tryit: "Find the block of the day when nobody can reach you and protect it for the work that needs thinking.",
        attrib: ["self", "witness"], grade: "reported", source: "Michael Shear, 'Obama After Dark', New York Times (2016); Obama, A Promised Land" },
      { id: "dinner", cat: "energy", name: "Dinner at 6:30", stage: "Presidency",
        what: "Kept family dinner at about 6:30 as a fixed point in the schedule, then returned to work afterwards.",
        volume: "Most evenings in Washington",
        mechanism: "A fixed boundary that the schedule had to work around, rather than the other way round.",
        cost: "It moved the work later into the night.",
        tryit: "Put one personal commitment in the diary as immovable; let the work flow around it.",
        attrib: ["self", "witness"], grade: "reported", source: "Lewis, 'Obama's Way'; Shear (2016)" },
      { id: "memo", cat: "machine", name: "Agree, disagree, let's discuss", stage: "Presidency",
        what: "Decision memos were set up to end with three boxes for him to tick — agree, disagree, or let's discuss.",
        volume: null,
        mechanism: "A memo that ends in a choice forces staff to frame a decision rather than a survey, and lets the principal clear routine items quickly.",
        cost: "The 'let's discuss' box could become a way to postpone.",
        tryit: "End every recommendation you send with the decision you need and the options in a line each.",
        attrib: ["witness"], grade: "reported", source: "Michael Lewis, 'Obama's Way', Vanity Fair (2012)" },
      { id: "suits", cat: "energy", name: "Paring down decisions", stage: "Presidency",
        what: "Wore only grey or blue suits and did not want to decide what to eat or wear, because there were too many other decisions to make.",
        volume: null,
        mechanism: "Decision fatigue is real enough to plan around: routine choices are spent attention.",
        cost: "Trivial; and the occasional tan suit became a news story.",
        tryit: "Make the trivial choices once — a uniform, a standing lunch order — and keep your attention for clients.",
        attrib: ["self"], grade: "reported", source: "Lewis, 'Obama's Way' (2012)" },
      { id: "longhand", cat: "prep", name: "Writing it himself", stage: "Throughout",
        what: "Wrote his books and many key speeches himself and edited speechwriters' drafts in longhand on yellow legal pads — including the 2004 convention keynote that made his name.",
        volume: null,
        mechanism: "Writing is thinking: owning the words meant owning the argument, and audiences heard a single voice.",
        cost: "Time, and late-night rewrites for the speechwriters.",
        tryit: "Draft your most important client letters yourself before anyone polishes them.",
        attrib: ["self", "witness"], grade: "documented", source: "Obama, A Promised Land; accounts of his speechwriters" },
      { id: "organiser", cat: "machine", name: "The organiser's model", stage: "1985–88 Chicago; 2007–08 campaign",
        what: "Spent three years as a community organiser on Chicago's South Side, where the method was listening one-on-one and building local leaders. His 2008 campaign trained volunteers in the same model and gave them responsibility for their own neighbourhoods.",
        volume: null,
        mechanism: "A campaign built on trained volunteers scales in a way a candidate's schedule cannot.",
        cost: "The volunteer network proved hard to keep alive once in government.",
        tryit: "Train others to do what you do, and give them real ownership of a patch.",
        attrib: ["self", "biographer"], grade: "documented", source: "Obama, Dreams from My Father; David Remnick, The Bridge" },
      { id: "afghanreview", cat: "prep", name: "Deliberating before deciding", stage: "Autumn 2009 — Afghanistan review",
        what: "Ran a strategy review of the Afghanistan war over about three months of meetings in the Situation Room before announcing the troop increase at West Point on 1 December 2009, pressing commanders on their assumptions and timelines.",
        volume: "About three months",
        mechanism: "Forcing the advocates to defend their assumptions in front of each other exposed the trade-offs and gave him a timeline to hold them to.",
        cost: "Opponents called it dithering; senior military leaders felt boxed in.",
        tryit: "For a big, hard-to-reverse decision, make the experts argue it out in front of you before you commit.",
        attrib: ["witness", "biographer"], grade: "documented", source: "Bob Woodward, Obama's Wars (2010); Obama, A Promised Land" }
    ],
    books: ["a-promised-land", "the-bridge-remnick", "laskas-to-obama"]
  },

